//! A web framework on top of [`axum`] with first-class OpenAPI documentation support,
//! ported from [Linz](https://github.com/apskhem/linz).
//!
//! Endpoints are declared once, and that declaration drives everything:
//!
//! - **Validation**: request parts (query, headers, path, cookies, body) are validated
//!   against the JSON schemas of their Rust types, generated by [`schemars`]. Failures
//!   respond `400` with [JSON:API](https://jsonapi.org/format/#errors) errors.
//! - **Typing**: handlers receive typed, deserialized values, and their response type is
//!   checked at compile time against the declared response.
//! - **Documentation**: an OpenAPI 3.1 document is generated from the same declarations and
//!   served with a docs viewer.
//!
//! # Example
//!
//! ```
//! use axum::Router;
//! use linz_rs::*;
//! use schemars::JsonSchema;
//! use serde::{Deserialize, Serialize};
//!
//! #[derive(Deserialize, JsonSchema)]
//! struct UserPath {
//!     user_id: u32,
//! }
//!
//! #[derive(Serialize, JsonSchema)]
//! struct User {
//!     id: u32,
//! }
//!
//! let api = Api::new()
//!     .get(
//!         "/users/:user_id",
//!         Endpoint::new("getUser")
//!             .path::<UserPath>()
//!             .returns(200, JsonBody::new::<User>())
//!             .response(404, true),
//!         |req, _ctx| async move { Ok(User { id: req.params.user_id }) },
//!     )
//!     .config(GroupConfig::new().tag("Users"));
//!
//! let app: Router = create_api(
//!     Router::new(),
//!     Api::new().nest("/v1", api),
//!     CreateApiConfig {
//!         docs: Some(DocsConfig {
//!             viewer: DocsViewer::Scalar,
//!             spec: BuilderConfig::new("My API", "1.0.0"),
//!             docs_path: "/docs".into(),
//!             spec_path: "/openapi.json".into(),
//!             theme: None,
//!         }),
//!         ..Default::default()
//!     },
//! )
//! .expect("valid routes");
//! ```
//!
//! # Where to start
//!
//! - [`Api`] collects routes; [`Endpoint`] declares an operation; [`create_api`] registers
//!   them on an [`axum::Router`].
//! - Bodies: [`JsonBody`], [`FormDataBody`], [`UrlEncodedBody`], [`OctetStreamBody`],
//!   [`TextBody`], [`HtmlBody`].
//! - Errors: handlers return [`ApiError`]; registration returns [`LinzError`].
//! - Authentication: [`Security`].
//!
//! The repository's `MANUAL.md` is a complete guide with how-to recipes.

